/** The address of an artwork of the globe at a width (160, 240 or 480 px). */
export function globeUrl(id: string, width: number): string {
  const f = GLOBE_FILES[`${id}_${width}`];
  if (!f) throw new Error(`globe picture ${id}_${width} is not in the manifest`);
  return `/assets/landing/globe/${id}_${width}.${f[0]}.webp`;
}

/** Every file of the list, for the build's check: name (globe/<id>_<width>) -> [content hash, bytes]. */
export const GLOBE_HASH = Object.fromEntries(Object.entries(GLOBE_FILES).map(([k, v]) => [`globe/${k}`, v]));
